import { ValidationError } from '../../domain/errors/DomainError';
import { OrderRepository } from '../../domain/order/OrderRepository';
import { parseOrderStatus } from '../../domain/order/OrderStatus';
import { OrderDto, toOrderDto } from '../dto/OrderDto';
import { requireOrder } from '../services/requireOrder';

/** Moves an order one step along its lifecycle (paid, packed, shipped or delivered). */
export class AdvanceOrderUseCase {
  constructor(private readonly orders: OrderRepository) {}

  execute(orderId: string, targetStatus: string): OrderDto {
    const target = parseOrderStatus(targetStatus);
    if (target === 'cancelled') {
      throw new ValidationError('Use the cancel operation to cancel an order');
    }
    const order = requireOrder(this.orders, orderId);

    order.advanceTo(target);
    this.orders.save(order);
    return toOrderDto(order);
  }
}

